#include <iostream>

int main()
{
    int a{};
    int b{};
    int c{};
    if (!(std::cin >> a >> b >> c)) return 0;

    bool valid{ a + b > c && a + c > b && b + c > a };

    if (!valid)
        std::cout << "not a triangle\n";
    else if (a == b && b == c)
        std::cout << "equilateral\n";
    else if (a == b || b == c || a == c)
        std::cout << "isosceles\n";
    else
        std::cout << "scalene\n";

    return 0;
}
